//go:build goexperiment.simd && amd64

package simd

import (
	"internal/cpu"
	"simd/archsimd"
)

// Match Go's effective CPU and carryless-multiply eligibility, capped at the
// widest representation generated by LLGo's Midway. LLVM instruction-level
// multiversioning is independent of this portable vector-width selection.
func archMaxVectorSize() (size, allFeatureSize int) {
	if archsimd.X86.AVX() {
		size, allFeatureSize = 128, 128
	}
	if archsimd.X86.AVX2() {
		size = 256
		if cpu.X86.HasVPCLMULQDQ {
			allFeatureSize = 256
		}
	}
	return
}
